import random

class Asset:   
    def __init__(self, ascii_chars, blink_style=None, blink_rate=1, blink_rate_init=0, color=None, reverse=False):
        if not all(isinstance(line, str) for line in ascii_chars):
            raise ValueError("ascii_chars must be a list of strings")
        if not all(len(line) == len(ascii_chars[0]) for line in ascii_chars):
            raise ValueError("all strings in ascii_chars must be of the same length")
        
        self.ascii_chars = ascii_chars
        self.color = color
        self.blink_rate_init = blink_rate_init
        self.blink_rate = blink_rate
        self.blink_style = blink_style
        
        self.blink_state = 0
        if reverse:
            self.blink_state = 1

        self.color_index = -1

        if self.blink_rate_init is None:
            self.blink_rate_init = random.randint(0, self.blink_rate or 1)
    
    def shape(self):
        try:
            return len(self.ascii_chars), len(self.ascii_chars[0])
        except IndexError:
            return 0, 0
        
    def get(self):
        return self.ascii_chars
    
    def mirror_horizontal(self):
        self.ascii_chars = [line[::-1] for line in self.ascii_chars]
        return self


